return ['domain'=>'shd-instagram-feed','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'SHD Instagram Feed 0.1.0','pot-creation-date'=>'2026-11-09T09:31:04+00:00','po-revision-date'=>'2026-11-09 09:26+0000','messages'=>['SHD Instagram Feed'=>'SHD Instagram Feed','https://shdigital.ch/'=>'https://shdigital.ch/','Shows your latest Instagram posts in a fast, accessible slider with an Elementor widget. Posts and images are synced in the background and stored locally, so visitors never load anything from Instagram.'=>'Zeigt Ihre neuesten Instagram-Beiträge in einem schnellen, barrierefreien Slider mit Elementor-Widget. Beiträge und Bilder werden im Hintergrund synchronisiert und lokal gespeichert, Besucher laden also nichts von Instagram.','SH Digital'=>'SH Digital','Instagram Feed'=>'Instagram-Feed','Settings'=>'Einstellungen','Posts to keep'=>'Gespeicherte Beiträge','Check for new posts'=>'Nach neuen Beiträgen suchen','The newest posts are kept with their images. Older images are deleted automatically.'=>'Die neuesten Beiträge werden mit ihren Bildern gespeichert. Ältere Bilder werden automatisch gelöscht.','Every hour'=>'Stündlich','Twice a day'=>'Zweimal täglich','Once a day'=>'Einmal täglich','Please paste an access token.'=>'Bitte fügen Sie ein Zugriffstoken ein.','Instagram did not accept this token: %s'=>'Instagram hat dieses Token nicht akzeptiert: %s','Connected to @%s.'=>'Verbunden mit @%s.','Disconnected. The cached posts and images were deleted.'=>'Verbindung getrennt. Die gespeicherten Beiträge und Bilder wurden gelöscht.','Disconnected. The widget keeps showing the cached posts until you connect again.'=>'Verbindung getrennt. Das Widget zeigt weiterhin die gespeicherten Beiträge, bis Sie das Konto wieder verbinden.','Sync failed: %s'=>'Synchronisierung fehlgeschlagen: %s','%d post is up to date.'=>'%d Beitrag ist aktuell.' . "\0" . '%d Beiträge sind aktuell.','%d new image imported.'=>'%d neues Bild importiert.' . "